import{_ as t,c as o,o as r,al as a}from"./chunks/framework.B3j7FRen.js";const h=JSON.parse('{"title":"QueryTool","description":"","frontmatter":{},"headers":[],"relativePath":"development/query-tool.md","filePath":"development/030_query-tool.md","lastUpdated":1748439130000}'),n={name:"development/query-tool.md"};function i(u,e,s,p,d,l){return r(),o("div",null,e[0]||(e[0]=[a(`<h1 id="querytool" tabindex="-1">QueryTool <a class="header-anchor" href="#querytool" aria-label="Permalink to &quot;QueryTool&quot;">​</a></h1> <h2 id="what-is-it" tabindex="-1">What is it? <a class="header-anchor" href="#what-is-it" aria-label="Permalink to &quot;What is it?&quot;">​</a></h2> <p>QueryTool is a simple command-driven search tool that provides a demonstration of the querying features of BlackLab. It allows you to search an index using different query languages:</p> <ul><li><a href="/guide/corpus-query-language.html">BlackLab Corpus Query Language</a> (BCQL), aimed at finding linguistic patterns in large text corpora. A dialect of the query language developed at the University of Stuttgard for the IMS Corpus Workbench (CWB) and is used in other corpus search systems as well, notably the Lexicom Sketch Engine.</li> <li><a href="https://lucene.apache.org/core/8_0_0/queryparser/org/apache/lucene/queryparser/classic/package-summary.html#Overview" target="_blank" rel="noreferrer">Lucene Query Language</a>, the query parser supplied with Lucene. A familiar syntax for including/excluding terms, similar to how many search engines operate.</li> <li>Rudimentary support for <a href="http://zing.z3950.org/cql/intro.html" target="_blank" rel="noreferrer">SRU CQL</a> (Contextual Query Language), a query language used by libraries around the world.</li></ul> <p>Note that BCQL is by far the best-supported query language.</p> <h2 id="starting-the-querytool" tabindex="-1">Starting the QueryTool <a class="header-anchor" href="#starting-the-querytool" aria-label="Permalink to &quot;Starting the QueryTool&quot;">​</a></h2> <p>You can start QueryTool to search your own data set by running it from the commandline. To learn how to quickly index and search a corpus, see <a href="/guide/getting-started.html">Getting Started</a>.</p> <h2 id="paging-sorting-and-grouping" tabindex="-1">Paging, sorting and grouping <a class="header-anchor" href="#paging-sorting-and-grouping" aria-label="Permalink to &quot;Paging, sorting and grouping&quot;">​</a></h2> <p>As a first query, type &quot;de&quot; (the) and press Enter. The first twenty hits for this query are shown. To page through the results, use the commands “next” and “previous” (or their one-letter abbreviations). You can also change the number of hits displayed per page by using the “pagesize” command followed by a number.</p> <p>You can sort the hits using the command “sort &lt;criterium&gt;”. The criterium can be “match”, “left” or “right”. “match” sorts by matched text, “left” sorts by left context (the text to the left of the matched text), and “right” sorts by right context. You can also specify an annotation to sort on, e.g. word, lemma, or pos. If you don&#39;t specify this, hits will be sorted by word.</p> <p>You can group the hits using “group &lt;criterium&gt;”. Valid values are again “match”, “left” or “right”. Here, “left” and “right” group on the single word occurring to the left or right of the matched text. Just like sort, you can optionally specify an annotation (word, lemma, pos) to group on. Word is the default.</p> <p>Once you group hits, you enter group mode. The groups are displayed in columns: group number, group size and group identity. If there are many groups, you can page through the groups using the same command as for hits. You can also sort the groups by “identity” or “size”.</p> <p>To examine the hits in a group, enter “group n”, where n is the group number displayed at the beginning of the line (the second number is the group size). To leave group mode and go back to showing all hits, enter “hits”. To get back to group mode, enter “groups”.</p> <h2 id="blacklab-corpus-query-language-bcql" tabindex="-1">BlackLab Corpus Query Language (BCQL) <a class="header-anchor" href="#blacklab-corpus-query-language-bcql" aria-label="Permalink to &quot;BlackLab Corpus Query Language (BCQL)&quot;">​</a></h2> <p>The demo starts out in BlackLab Corpus Query Language (BCQL) mode, which is the most powerful of the supported languages. This query language expresses queries as sequences of token queries. It is therefore mainly useful to find specific types of phrases in a larger text.</p> <p>An example of a simple query (note that the quotes are required):</p> <pre><code>&quot;de&quot; &quot;sta.\\*&quot;
</code></pre> <p>This searches for the word “de” followed by a word starting with “sta”. As you can see, regular expressions can be used to build token queries.</p> <p>Equivalent to the above query is:</p> <pre><code>[word=&quot;de&quot;] [word=&quot;sta.\\*&quot;]
</code></pre> <p>In addition to using regular expressions to express single-token restrictions, a similar notation can be used to express restrictions on sequences of tokens. For example:</p> <pre><code>&quot;der.\\*&quot;{2,}
</code></pre> <p>This query finds two or more successive words starting with &quot;der&quot;. You can also use the regular expression operators such as *, + and ? to build multi-token regular expressions:</p> <pre><code>&quot;in&quot; &quot;de&quot;? &quot;gang&quot; &quot;g.\\*&quot;
</code></pre> <p>If your corpus is tagged with headword and part of speech (the supplied test set is), you can search for these features as well:</p> <pre><code>[hw=&quot;zijn&quot;] [hw=&quot;blijven&quot;]
</code></pre> <p>This find forms of these verbs (“to be” and “to stay”) occurring together.</p> <pre><code>[pos=&quot;a.\\*&quot;]+ &quot;man&quot;
</code></pre> <p>This finds the word &quot;man&quot; with one or more adjectives applied to it.</p> <h2 id="querytool-reference" tabindex="-1">QueryTool reference <a class="header-anchor" href="#querytool-reference" aria-label="Permalink to &quot;QueryTool reference&quot;">​</a></h2> <h3 id="corpusql-examples" tabindex="-1">CorpusQL examples <a class="header-anchor" href="#corpusql-examples" aria-label="Permalink to &quot;CorpusQL examples&quot;">​</a></h3> <p>Find words starting with &quot;sta&quot;:</p> <pre><code>&quot;sta.\\*&quot;
</code></pre> <p>Find &quot;man&quot; preceded by at least 2 adjectives:</p> <pre><code>[type=&quot;a.\\*&quot;]{2,} &quot;man&quot;
</code></pre> <p>Find &quot;stad&quot; and &quot;dorp&quot; with one word in between:</p> <pre><code>&quot;stad&quot; [] &quot;dorp&quot;
</code></pre> <p>Find &quot;stad&quot; and &quot;dorp&quot; with 2-10 words in between:</p> <pre><code>&quot;stad&quot; []{2,10} &quot;dorp&quot;
</code></pre> <p>Find all words:</p> <pre><code>[]
</code></pre> <p>Find all bigrams:</p> <pre><code>[] []
[]{2}
</code></pre> <p>&quot;de&quot; at the start of a named entity:</p> <pre><code>&lt;ne\\&gt; &quot;de&quot;
</code></pre> <p>&quot;poorter&quot; at the end of a named entity:</p> <pre><code>&quot;poorter&quot; &lt;/ne\\&gt;
</code></pre> <p>Named entities containing &quot;de&quot;:</p> <pre><code>&lt;ne/\\&gt; containing &quot;de&quot;
</code></pre> <p>&quot;de&quot; within a named entity:</p> <pre><code>&quot;de&quot; within &lt;ne/\\&gt;
</code></pre> <p>All named entities:</p> <pre><code>&lt;ne/\\&gt;
</code></pre> <p>All persons:</p> <pre><code>&lt;ne type=&quot;per&quot;/\\&gt;
</code></pre> <p>Person names containing &quot;van&quot;:</p> <pre><code>&lt;ne type=&quot;per&quot;/\\&gt; containing &quot;van&quot;
</code></pre> <p>Locations starting with &quot;de&quot;:</p> <pre><code>&lt;ne type=&quot;loc&quot; /\\&gt; containing &lt;ne\\&gt; &quot;de&quot;
</code></pre> <h3 id="other-commands" tabindex="-1">Other commands <a class="header-anchor" href="#other-commands" aria-label="Permalink to &quot;Other commands&quot;">​</a></h3> <p>Grouping</p> <pre><code>group match
group match lemma
group match pos
</code></pre> <p>Sorting</p> <pre><code>sort left
sort right lemma
</code></pre> <p>Paging through results:</p> <pre><code>n(ext)
p(revious)
</code></pre> <p>Change context size (number of words around hit):</p> <pre><code>context 3
context 10
</code></pre> <p>Show document title in KWIC view:</p> <pre><code>doctitle on
doctitle off
</code></pre> <p>Case/diacritics-sensitivity:</p> <pre><code>sensitive on
sensitive off
</code></pre> <p>Filter on metadata (uses Lucene query syntax):</p> <pre><code>filter title.level1:&quot;courant&quot;
filter author.level1:&quot;jansen&quot;
filter author.level1:&quot;sterkenburg&quot; author.level2:&quot;sterkenburg&quot;
filter (Filter weer leegmaken)
</code></pre> <p>Show index structure:</p> <pre><code>struct
structure
</code></pre> <h3 id="commandline-editing" tabindex="-1">Commandline editing <a class="header-anchor" href="#commandline-editing" aria-label="Permalink to &quot;Commandline editing&quot;">​</a></h3> <p>Commandline editing is available if the <a href="http://jline.sourceforge.net/" target="_blank" rel="noreferrer">JLine</a> JAR is found on the classpath.</p>`,155)]))}const g=t(n,[["render",i]]);export{h as __pageData,g as default};
